#include "ActualAuthoringRecording.h"
#include "ResearchBibliography.h"
#include "ResearchSettings.h"
#include <QTcpServer>
#include <QTcpSocket>
#include <memory>
using namespace Research;
static void acquireDialog(QWidget *parent,std::function<void(QDialog*)> callback){auto *timer=new QTimer(qApp);QObject::connect(timer,&QTimer::timeout,timer,[=]{auto *d=parent->findChild<QDialog*>("researchBibAcquire");if(!d||!d->isVisible())return;timer->stop();timer->deleteLater();callback(d);});timer->start(20);}
int main(int argc,char **argv){const auto report=argument(1);argc=1;TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer::singleShot(60,&app,[&]{QJsonArray checks,requests;int failures=0;auto check=[&](const QString &name,bool pass){checks.append(QJsonObject{{"name",name},{"passed",pass}});failures+=!pass;put(report,QJsonDocument(QJsonObject{{"checks",checks},{"requests",requests},{"failures",failures},{"devicePixelRatio",qApp->primaryScreen()->devicePixelRatio()}}).toJson());};const auto folder=QFileInfo(report).absolutePath();put(folder+"/main.tex","\\documentclass{article}\n\\begin{document}Research\\end{document}\n");Tw::Settings().setValue("openPDFwithTeX",false);auto *w=new TeXDocumentWindow(folder+"/main.tex");w->show();settle();
acquireDialog(w,[&](QDialog *d){d->findChild<QLineEdit*>("researchBibNew_key")->setText("hu2026");d->findChild<QLineEdit*>("researchBibNew_title")->setText("中文与 {mathematics}");d->findChild<QLineEdit*>("researchBibNew_author")->setText("Hu, Jieyang");d->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});const auto manual=acquireBibliography(w,0);check("manual reference returns valid BibTeX with balanced mathematics",parseBibliography(manual).error.isEmpty()&&parseBibliography(manual).records.size()==1&&manual.contains("中文与 {mathematics}"));check("manual draft creates no bibliography before confirmation",QDir(folder).entryList({"*.bib"}).isEmpty());
acquireDialog(w,[&](QDialog *d){d->findChild<QLineEdit*>("researchBibNew_key")->setText("cancelled");key(d,Qt::Key_Escape);});check("manual acquisition Esc discards the draft",acquireBibliography(w,0).isEmpty());
QTcpServer server;check("private protocol fixture binds an ephemeral loopback port",server.listen(QHostAddress::LocalHost,0));QObject::connect(&server,&QTcpServer::newConnection,&app,[&]{while(server.hasPendingConnections()){auto *socket=server.nextPendingConnection();auto buffer=std::make_shared<QByteArray>();QObject::connect(socket,&QTcpSocket::readyRead,socket,[&,socket,buffer]{buffer->append(socket->readAll());const int boundary=buffer->indexOf("\r\n\r\n");if(boundary<0)return;auto headers=buffer->left(boundary);const auto length=QRegularExpression("(?i)Content-Length: (\\d+)").match(QString::fromLatin1(headers));if(!length.hasMatch()||buffer->size()-boundary-4<length.captured(1).toInt())return;auto request=QJsonDocument::fromJson(buffer->mid(boundary+4,length.captured(1).toInt())).object();requests.append(request);QJsonValue result;if(request["method"]=="item.search")result=QJsonArray{QJsonObject{{"citekey","hu2026"},{"title","中文研究"}},QJsonObject{{"citation-key","coauthor2025"},{"title","Related evidence"}}};else result="@article{hu2026,title={中文研究},author={Hu, Jieyang},year={2026}}\n@book{coauthor2025,title={Related evidence}}\n";const auto payload=QJsonDocument(QJsonObject{{"jsonrpc","2.0"},{"id",request["id"]},{"result",result}}).toJson(QJsonDocument::Compact);socket->write("HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nConnection: close\r\nContent-Length: "+QByteArray::number(payload.size())+"\r\n\r\n"+payload);socket->disconnectFromHost();QObject::disconnect(socket,&QTcpSocket::readyRead,nullptr,nullptr);});QObject::connect(socket,&QTcpSocket::disconnected,socket,&QObject::deleteLater);}});
const QUrl endpoint(QString("http://127.0.0.1:%1/better-bibtex/json-rpc").arg(server.serverPort()));
acquireDialog(w,[&](QDialog *d){d->findChild<QLineEdit*>("researchBibOnlineQuery")->setText("Hu");for(auto *b:d->findChildren<QPushButton*>())if(b->text()==words("查找","Search"))b->click();auto *list=d->findChild<QListWidget*>("researchBibOnlineResults");check("Zotero protocol search returns selectable local entries",waitFor([&]{return list->count()==2;},15000));if(list->count()!=2){d->reject();return;}list->item(0)->setSelected(true);list->item(1)->setSelected(true);d->grab().save(folder+"/zotero-protocol-picker.png");d->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();QTimer::singleShot(18000,d,&QDialog::reject);});const auto selected=acquireBibliography(w,3,endpoint);check("Zotero protocol export preserves multiple entries",parseBibliography(selected).error.isEmpty()&&parseBibliography(selected).records.size()==2);check("local service receives only explicit query and selected citation keys",requests.size()==2&&requests[0].toObject()["params"].toArray()==QJsonArray{"Hu"}&&requests[1].toObject()["params"].toArray()==QJsonArray{QJsonArray{"hu2026","coauthor2025"},"Better BibTeX"});
acquireDialog(w,[](QDialog *d){key(d,Qt::Key_Escape);});check("Zotero picker cancellation sends no request",acquireBibliography(w,3,endpoint).isEmpty()&&requests.size()==2);
acquireDialog(w,[&](QDialog *d){d->findChild<QLineEdit*>("researchBibOnlineQuery")->setText("cancel before dispatch");for(auto *b:d->findChildren<QPushButton*>())if(b->text()==words("查找","Search"))b->click();key(d,Qt::Key_Escape);});check("cancelled scheduled lookup never starts a background process",acquireBibliography(w,3,endpoint).isEmpty());settle(100);check("cancelled lookup sends no late request",requests.size()==2);
if(qEnvironmentVariableIsSet("TEXLINE_LIVE_REFERENCE_LOOKUP")){acquireDialog(w,[&](QDialog *d){d->findChild<QLineEdit*>("researchBibOnlineQuery")->setText("10.1038/s41586-021-03819-2");for(auto *b:d->findChildren<QPushButton*>())if(b->text()==words("查找","Search"))b->click();auto *list=d->findChild<QListWidget*>("researchBibOnlineResults");const bool found=waitFor([&]{return list->count()>0;},26000);check("live DOI lookup obtains a bibliographic record",found);if(found){list->setCurrentRow(0);d->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();}else d->reject();});const auto online=acquireBibliography(w,2);check("live DOI selection returns parsable BibTeX",!online.isEmpty()&&parseBibliography(online).error.isEmpty());}
check("acquisition did not edit the manuscript",bytes(folder+"/main.tex")=="\\documentclass{article}\n\\begin{document}Research\\end{document}\n");w->close();settle();app.exit(failures?1:0);
});return app.exec();}
